class Task:
    def __init__(self, title, done=False):
        self.title = title
        self.done = done

    def complete(self):
        self.done = True

    def __str__(self):
        return f"[{'x' if self.done else ' '}] {self.title}"

class Shape:
    def area(self):
        raise NotImplementedError

class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return 3.14159 * self.r * self.r

class Rect(Shape):
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h

tests.code:
try:
    Shape().area()
except NotImplementedError:
    pass
else:
    raise AssertionError('Shape().area() should raise NotImplementedError.')

