questions.solution:
class Team:
    def __init__(self, name):
        self.name = name
        self.members = []

    def join(self, person):
        self.members.append(person)

class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    @property
    def grade(self):
        return self._grade

    @grade.setter
    def grade(self, value):
        if not 0 <= value <= 100:
            raise ValueError("grade must be 0-100")
        self._grade = value

    @property
    def passed(self):
        return self._grade >= 50

tests.code:
try:
    Student('Ben', 101)
except ValueError:
    pass
else:
    raise AssertionError('A grade above 100 should raise ValueError.')

