questions.solution:
class Book:
    def __init__(self, book_id, title):
        self.book_id = book_id
        self.title = title
        self.borrower = None

class Library:
    def __init__(self):
        self._books = {}

    def add(self, book):
        self._books[book.book_id] = book

    def _get(self, book_id):
        if book_id not in self._books:
            raise KeyError(book_id)
        return self._books[book_id]

    def checkout(self, book_id, member):
        book = self._get(book_id)
        if book.borrower is not None:
            raise ValueError("already checked out")
        book.borrower = member

    def return_book(self, book_id):
        self._get(book_id).borrower = None

    def available(self):
        return sorted(b.title for b in self._books.values() if b.borrower is None)

tests.code:
lib = Library()
lib.add(Book(1, 'Dune'))
lib.checkout(1, 'ana')
try:
    lib.checkout(1, 'ben')
except ValueError:
    pass
else:
    raise AssertionError('Checking out a book that is out should raise ValueError.')
try:
    lib.checkout(9, 'ben')
except KeyError:
    pass
else:
    raise AssertionError('Unknown ids should raise KeyError.')
